def eligible(now,start,end,member,product):
    return start <= now < end and member and product

def discount(amount,fixed,rate):
    return min(1000, fixed if fixed is not None else int(amount*rate))

class Usage:
    def __init__(self,limit): self.limit,self.used=limit,0
    def use(self):
        if self.used >= self.limit: return False
        self.used += 1
        return True
    def cancel(self):
        self.used -= 1
        return True

def checkout(price,eligibility):
    amount=price()
    allowed=eligibility()
    return amount if allowed else None

