import unittest
from coupon import eligible, discount, Usage, checkout

class Eligibility(unittest.TestCase):
    def test_period(self):
        for now, expected in [(9,False),(10,True),(19,True),(20,False)]:
            with self.subTest(now=now):
                self.assertEqual(eligible(now,10,20,True,True),expected)
    def test_membership(self):
        self.assertFalse(eligible(15,10,20,False,True))
        self.assertFalse(eligible(15,10,20,True,False))
class Money(unittest.TestCase):
    def test_fixed(self):
        self.assertEqual(discount(3000,500,None),500)
    def test_percent(self):
        self.assertEqual(discount(999,None,0.1),99)
    def test_cap(self):
        self.assertEqual(discount(20000,None,0.1),1000)
class UsageTests(unittest.TestCase):
    def test_limit(self):
        u=Usage(2)
        self.assertTrue(u.use())
        self.assertTrue(u.use())
        self.assertFalse(u.use())
    def test_cancel(self):
        u=Usage(1)
        u.use()
        self.assertTrue(u.cancel())
class ReadOrder(unittest.TestCase):
    def test_calls(self):
        seen=[]
        checkout(lambda: seen.append('price') or 100, lambda: seen.append('eligibility') or True)
        self.assertEqual(seen,['price','eligibility'])

